import {curriculum,phases,videos,totalHours} from './course.js';
import {cloud} from './cloud.js';

const STORAGE_KEY='v2_v3';
const LEGACY_STORAGE_KEY=['dev','launch_duo_v3'].join('');
const $=(sel,scope=document)=>scope.querySelector(sel);
const htmlEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const duration=seconds=>{seconds=Math.max(0,Math.floor(Number(seconds)||0));return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`};
const shortDuration=seconds=>`${(seconds/3600).toFixed(1)}h`;
const fractionalPercent=(n,d)=>d?((n/d)*100).toFixed(1):'0.0';
const humanTime=timestamp=>timestamp?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'}).format(new Date(timestamp)):'No activity yet';
const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));
const todayISO=()=>{const f=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'});let p=f.formatToParts(new Date());let g=t=>p.find(x=>x.type===t)?.value;return `${g('year')}-${g('month')}-${g('day')}`;};
function newState(){return {version:3,users:[{id:'local-you',name:'Praveen'},{id:'local-friend',name:'Sanchita'}],activeId:'local-you',progress:{},activeDays:{},startDates:{},projects:{},videoStatus:{},settings:{},quizSelections:{}}}
function load(){try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY) ?? localStorage.getItem(LEGACY_STORAGE_KEY));if(v&&v.version===3&&Array.isArray(v.users)&&v.progress&&typeof v.progress==='object'){const result={...newState(),...v};const primary=result.users.find(u=>u.id==='local-you');const friend=result.users.find(u=>u.id==='local-friend');if(primary)primary.name='Praveen';else result.users.push({id:'local-you',name:'Praveen'});if(friend)friend.name='Sanchita';else result.users.push({id:'local-friend',name:'Sanchita'});return result}}catch{}return newState()}
let state=load(),peer=null,running=null,lastCloudError='',cloudSyncTimers=new Map(),metaSyncTimer=0,toastTimeout=0,currentFilter='',currentPhase='all',videoSelected='boot',syncing=false,duoSelectedDay=1,lastPeerRefresh=0;
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch(e){message('Storage is unavailable or full. Export a backup.',true)}}
function message(m,error=false){const el=$('#toast');if(!el)return;el.textContent=m;el.style.background=error?'#4a222c':'#1b3b32';el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),4500)}
const user=()=>state.users.find(u=>u.id===state.activeId)||state.users[0];
const isCloud=()=>state.activeId.startsWith('cloud:');
const ownCloudId=()=>cloud.session?.user?.id;
function getRecord(id,day){return state.progress?.[id]?.[day]||{blocks:[],seconds:{},notes:'',quiz:null,updatedAt:0};}
function ensureRecord(id,day){state.progress[id]??={};state.progress[id][day]??={blocks:[],seconds:{},notes:'',quiz:null,updatedAt:Date.now()};return state.progress[id][day]}
function percent(n,d){return d?Math.round(n*100/d):0}
function isDayComplete(record){return [0,1,2,3,4,5].every(i=>record?.blocks?.includes(i))}
function stats(id){const days=state.progress[id]||{};let completed=0,doneBlocks=0,seconds=0,quizzes=0;const dates=new Set();let lastUpdated=0;
 for(const entry of Object.values(days)){if(isDayComplete(entry)){completed++;if(entry.completedAt)dates.add(entry.completedAt)}doneBlocks+=(entry.blocks||[]).length;seconds+=Object.values(entry.seconds||{}).reduce((a,b)=>a+(+b||0),0);if(entry.quiz?.correct)quizzes++;lastUpdated=Math.max(lastUpdated,Number(entry.updatedAt)||0)}
 let streak=0;if(dates.size){let d=new Date(`${todayISO()}T12:00:00Z`);if(!dates.has(todayISO()))d.setUTCDate(d.getUTCDate()-1);for(let i=0;i<120;i++){const ds=d.toISOString().slice(0,10);if(!dates.has(ds))break;streak++;d.setUTCDate(d.getUTCDate()-1)}}
 let projectCount=Object.values(state.projects[id]||{}).filter(p=>p?.done).length;
 const score=doneBlocks*10+completed*20+quizzes*5+projectCount*25;
 return {completed,doneBlocks,seconds,quizzes,projectCount,score,lastUpdated,percent:percent(completed,120),blockPercent:fractionalPercent(doneBlocks,720),streak};}

function getActiveDay(id=state.activeId){return clamp(Number(state.activeDays[id])||1,1,120)}
function setDay(day){let next=clamp(Number(day)||1,1,120);if(state.activeDays[state.activeId]!==next){state.activeDays[state.activeId]=next;save();queueMetaSave()}}
function mutate(day,modify){const rec=ensureRecord(state.activeId,day);modify(rec);rec.updatedAt=Date.now();if(isDayComplete(rec)&&!rec.completedAt)rec.completedAt=todayISO();if(!isDayComplete(rec))delete rec.completedAt;save();queueCloudSave(day)}
function queueCloudSave(day){if(!isCloud()||ownCloudId()!==state.activeId.slice(6))return;clearTimeout(cloudSyncTimers.get(day));cloudSyncTimers.set(day,setTimeout(()=>{cloudSyncTimers.delete(day);pushCloudDay(day)},900))}
function queueMetaSave(){if(!isCloud()||!cloud.authenticated)return;clearTimeout(metaSyncTimer);metaSyncTimer=setTimeout(pushCloudMeta,850)}
async function pushCloudMeta(){if(!isCloud()||!cloud.authenticated)return;const id=state.activeId;try{await cloud.saveMeta({projects:state.projects[id]||{},video_status:state.videoStatus[id]||{},active_day:getActiveDay(id)});setSyncBadge('☁ Projects and videos synced')}catch(e){lastCloudError=e.message;setSyncBadge('Offline: browser saved; retry sync')}}
async function pushCloudDay(day){if(!isCloud()||!cloud.authenticated)return;try{await cloud.saveDay(day,getRecord(state.activeId,day));lastCloudError='';setSyncBadge('☁ Cloud saved')}catch(err){lastCloudError=err.message;setSyncBadge('Offline changes saved locally')}}
function setSyncBadge(s){const e=$('#sync-status');if(e)e.textContent=s}
function progressBar(val,alt=false){return `<div class="progress-track"><div class="progress-fill ${alt?'alt':''}" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${clamp(val,0,100)}" style="width:${clamp(val,0,100)}%;${val>0?'min-width:3px;':''}"></div></div>`}
function navLink(path,icon,label){let route=location.hash.slice(1)||'/dashboard';let active=route===path||route.startsWith(path+'/');return `<a class="nav-item ${active?'active':''}" href="#${path}"><span class="nav-icon">${icon}</span>${label}</a>`}
function mobileLink(path,icon,label){let route=location.hash.slice(1)||'/dashboard';return `<a href="#${path}" class="${route===path||route.startsWith(path+'/')?'active':''}"><b>${icon}</b>${label}</a>`}
function layout(page){let u=user();let activeId=state.activeId;let mode=cloud.authenticated&&isCloud()?'☁ Cloud sync':'● Browser saved';const title=({'/dashboard':'Dashboard','/duo':'Duo Competition','/roadmap':'120-Day Roadmap','/videos':'Video Academy','/projects':'Projects & Practice','/progress':'Progress & Insights','/settings':'Settings'})[location.hash.slice(1)]||'Daily Lesson';
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/dashboard"><span class="brand-logo">⌘</span><span class="green">V2</span></a><div class="nav"><div class="nav-section">STUDY WORKSPACE</div>${navLink('/dashboard','◈','Dashboard')}${navLink('/duo','🏆','Praveen vs Sanchita')}${navLink('/roadmap','▦','120-Day Roadmap')}${navLink('/videos','▷','Video Academy')}${navLink('/projects','⌘','Projects & Practice')}${navLink('/progress','◷','Progress & Insights')}<div class="nav-section">YOUR WORKSPACE</div>${navLink('/settings','⚙','Profiles & Settings')}</div><div class="sidebar-spacer"></div><div class="side-note"><span class="eyebrow">YOUR MISSION</span><h3 style="margin-top:8px">120 days to build</h3><p>6 hours a day · Java, Spring Boot, React, DevOps & AI.</p><div class="progress-label"><span>Overall progress</span><strong>${stats(activeId).blockPercent}%</strong></div>${progressBar(Number(stats(activeId).blockPercent))}<p>${stats(activeId).doneBlocks} of 720 study blocks completed</p></div><div class="small muted" style="padding:8px">© 2027 V2</div></aside><div class="mobile-top"><a class="brand" href="#/dashboard"><span class="brand-logo">⌘</span><span class="green">V2</span></a><span class="small green">● Praveen × Sanchita</span></div><main class="main"><div class="topbar"><div><div class="eyebrow" style="margin-bottom:5px">SOFTWARE ENGINEERING ACADEMY</div><div class="small muted">${title} <span class="muted">·</span> <span id="sync-status">${mode}</span></div></div><div class="top-actions"><select aria-label="Choose learner" class="profile-select" id="profile-switch">${state.users.filter(x=>cloud.authenticated?x.id===`cloud:${ownCloudId()}`:x.id.startsWith('local-')).map(x=>`<option value="${htmlEscape(x.id)}" ${x.id===state.activeId?'selected':''}>${htmlEscape(x.name)}</option>`).join('')}</select><div class="avatar" aria-hidden="true">${htmlEscape(u.name.slice(0,1).toUpperCase())}</div></div></div><div class="content">${page}</div><div class="footer">V2 · Praveen & Sanchita. Local saving is automatic. Sharing between devices requires cloud sync.</div></main></div><nav class="mobile-nav">${mobileLink('/dashboard','⌂','Home')}${mobileLink('/duo','🏆','Duo')}${mobileLink('/roadmap','▦','Roadmap')}${mobileLink('/videos','▷','Videos')}${mobileLink('/projects','⌘','Projects')}${mobileLink('/progress','◷','Progress')}${mobileLink('/settings','⚙','Settings')}</nav>`;
 $('#profile-switch').addEventListener('change',e=>{pauseTimer();state.activeId=e.target.value;save();render()});
}
function duoProfiles(){
 if(cloud.authenticated){const own=`cloud:${ownCloudId()}`;const ownRow=state.users.find(u=>u.id===own);const teammate=peer?.members?.find(m=>m.id!==ownCloudId());
 const knownName=ownRow?.name||state.preferredLearner||'Praveen';const otherName=teammate?.display_name||(knownName==='Praveen'?'Sanchita':'Praveen');
 const mine={id:own,name:knownName,readonly:false,connected:true};const other={id:teammate?`cloud:${teammate.id}`:'none',name:otherName,readonly:true,connected:!!teammate};
 return knownName==='Sanchita'?[other,mine]:[mine,other];
 }
 return [{id:'local-you',name:'Praveen',readonly:false,connected:false},{id:'local-friend',name:'Sanchita',readonly:false,connected:false}];
}
function duoCards(){return duoProfiles().map((p,i)=>{const s=stats(p.id);return `<article class="panel duo-card ${i===1?'alt':''}"><span class="duo-avatar">${htmlEscape((p.name||'?')[0].toUpperCase())}</span><div><div class="duo-name">${htmlEscape(p.name)} ${p.id===state.activeId?'<span class="pill success">Your account</span>':''}${cloud.authenticated&&!p.connected?'<span class="pill">Awaiting connection</span>':''}</div>
<div class="progress-label" style="margin-top:13px"><span>Study blocks completed</span><strong>${s.blockPercent}%</strong></div>${progressBar(Number(s.blockPercent),i===1)}<div class="small muted">${s.doneBlocks} of 720 study blocks</div>
<div class="progress-label" style="margin-top:14px"><span>Fully finished days</span><strong>${s.completed}/120</strong></div>${progressBar(s.percent,i===1)}
<div class="duo-stats"><span><b>${s.score}</b> points</span><span><b>${shortDuration(s.seconds)}</b> studied</span><span><b>${s.quizzes}</b> quizzes</span><span><b>${s.projectCount}</b> projects</span></div></div></article>`}).join('')}
function syncNotice(){if(!cloud.authenticated)return `<div class="message warn duo-alert"><strong>Local practice mode.</strong> These two learner profiles are stored only in this browser. To compare progress from different devices, both Praveen and Sanchita must sign in to their own accounts and join the same team. <a href="#/settings">Enable cloud competition →</a></div>`;
 if(!peer?.members?.some(m=>m.id!==ownCloudId()))return `<div class="message warn duo-alert"><strong>Waiting for the second learner.</strong> Your cloud account is ready. Open <a href="#/settings">Settings</a> to create a study duo and share the invitation code. No teammate progress is shown until they join.</div>`;
 return `<div class="message duo-alert">☁ You are connected as a study duo. Each learner can edit only their own work. Teammate progress refreshes roughly every 15 seconds while the site is open. <button class="btn secondary small-btn" data-action="refresh-peer">↻ Refresh now</button>${lastPeerRefresh?`<span class="small muted">Last checked: ${htmlEscape(humanTime(lastPeerRefresh))}</span>`:''}</div>`}
function scorePanel(){let profiles=duoProfiles(),cards=profiles.map(p=>({...p,...stats(p.id)}));let rank=cards.every(p=>p.connected||!cloud.authenticated)&&cards[0].score!==cards[1].score?(cards[0].score>cards[1].score?cards[0].name:cards[1].name):null;
 return `<div class="panel competition-banner"><span class="eyebrow">FRIENDLY COMPETITION · TWO LEARNERS</span><div class="competition-top"><h2>🏆 ${rank?`${htmlEscape(rank)} leads the challenge`:'Your learning race starts here'}</h2><span class="pill gold">10 pts/block · 20 pts/completed day · 5 pts/correct quiz · 25 pts/project</span></div><div class="score-grid">${cards.map((p,i)=>`<div class="score-card ${i===1?'alt':''}"><div class="small muted">${htmlEscape(p.name)}</div><div class="score-number">${p.score}<span> pts</span></div><div class="small muted">${p.doneBlocks} study blocks · ${p.completed} full days</div></div>`).join('')}</div><p class="helper">Points are a motivational score based on completed tasks, not verified knowledge. Logging extra study time does not increase points.</p></div>`}
function recentActivity(p){const data=state.progress[p.id]||{};const found=Object.entries(data).filter(([d,v])=>(v.blocks?.length||0)>0||v.quiz||v.notes).sort((a,b)=>(b[1].updatedAt||0)-(a[1].updatedAt||0)).slice(0,6);
 if(!p.connected&&cloud.authenticated)return `<div class="empty">${htmlEscape(p.name)} has not joined the team yet.</div>`;
 if(!found.length)return `<div class="empty">No completed study blocks yet.</div>`;
 return found.map(([day,r])=>`<div class="activity-line"><span class="activity-dot">${r.blocks?.length===6?'✓':r.blocks?.length||0}</span><div><div class="small"><b>Day ${day}: ${htmlEscape(curriculum[Number(day)-1]?.title||'Lesson')}</b></div><div class="tiny muted">${r.blocks?.length||0}/6 blocks completed${r.quiz?.correct?' · Quiz correct':''} · ${htmlEscape(humanTime(r.updatedAt))}</div></div></div>`).join('');}
function duoPage(){const profiles=duoProfiles();let day=clamp(duoSelectedDay,1,120);const lesson=curriculum[day-1];return `<section class="page-heading"><div><div class="eyebrow">YOUR TWO-PERSON ENGINEERING CHALLENGE</div><h1>Praveen <span class="green">vs</span> Sanchita</h1><p>See each other's progress, completed activities, projects, quiz results and study effort.</p></div><button class="btn secondary" data-action="refresh-peer">↻ Sync teammate</button></section>${syncNotice()}${scorePanel()}<section class="grid two">${duoCards()}</section><section class="grid two">${profiles.map(p=>`<div class="panel"><h2>${htmlEscape(p.name)} · Recent work</h2><div class="activity-list">${recentActivity(p)}</div></div>`).join('')}</section><section class="panel"><div class="panel-heading"><div><h2>Compare exactly what you've completed</h2><div class="subtitle">Select a day to view each person's six study blocks side by side.</div></div><select id="duo-day-select" class="field compact-select" aria-label="Select day to compare">${curriculum.map(l=>`<option value="${l.day}" ${l.day===day?'selected':''}>Day ${l.day} · ${htmlEscape(l.title)}</option>`).join('')}</select></div><div class="grid two">${profiles.map((p,i)=>{let r=getRecord(p.id,day);return `<div class="compare-card ${i===1?'blue':''}"><h3>${htmlEscape(p.name)}</h3><div class="progress-label"><span>Day ${day} progress</span><strong>${r.blocks?.length||0}/6</strong></div>${progressBar(percent(r.blocks?.length||0,6),i===1)}${lesson.blocks.map((b,j)=>`<div class="compare-task"><span class="${r.blocks?.includes(j)?'check-green':'check-dim'}">${r.blocks?.includes(j)?'✓':'○'}</span><span>${htmlEscape(b.title)}</span></div>`).join('')}<p class="small muted" style="margin-top:13px">Quiz: ${r.quiz?.correct?'Correct ✓':r.quiz?'Attempted':'Not attempted'} · Study time: ${shortDuration(Object.values(r.seconds||{}).reduce((a,b)=>a+(Number(b)||0),0))}</p></div>`}).join('')}</div><div class="btn-row" style="margin-top:16px"><a class="btn primary" href="#/day/${day}">Open my Day ${day} lesson →</a><button class="btn secondary" data-action="duo-prev" ${day===1?'disabled':''}>← Previous day</button><button class="btn secondary" data-action="duo-next" ${day===120?'disabled':''}>Next day →</button></div></section><section class="panel"><div class="panel-heading"><h2>All 120 days — progress comparison</h2><span class="pill">✓ finished · number = blocks done</span></div><div class="duo-table-wrap"><table class="duo-table"><thead><tr><th>Day & topic</th><th>Praveen</th><th>Sanchita</th></tr></thead><tbody>${curriculum.map(l=>`<tr><td><button class="day-jump" data-action="duo-select-day" data-day="${l.day}">Day ${l.day} · ${htmlEscape(l.title)}</button></td>${profiles.map((p,i)=>{let r=getRecord(p.id,l.day);let n=r.blocks?.length||0;return `<td><span class="completion-tag ${n===6?'complete':n?'partial':''} ${i?'blue':''}">${n===6?'✓ Complete':`${n}/6 blocks`}</span></td>`}).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Project scoreboard</h2><div class="duo-table-wrap"><table class="duo-table"><thead><tr><th>Project</th><th>Praveen</th><th>Sanchita</th></tr></thead><tbody>${projects.map((proj,i)=>`<tr><td>${htmlEscape(proj[0])}</td>${profiles.map(p=>`<td>${state.projects[p.id]?.[i]?.done?`<span class="check-green">✓ Finished</span>${state.projects[p.id]?.[i]?.url?` <a href="${htmlEscape(state.projects[p.id][i].url)}" target="_blank" rel="noopener noreferrer">GitHub ↗</a>`:''}`:'Not finished'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}

function dashboard(){const d=getActiveDay(),lesson=curriculum[d-1],rec=getRecord(state.activeId,d),s=stats(state.activeId),v=videos[lesson.videoKey];return `<section class="page-heading"><div><div class="eyebrow">WELCOME BACK, ${htmlEscape(user().name.toUpperCase())}</div><h1 class="gradient-title">Build your future, daily.</h1><p>Your 2027 software engineering journey, one focused session at a time.</p></div><span class="pill success">◉ 120-DAY LEARNING CHALLENGE</span></section><section class="hero"><div><span class="pill success">DAY ${d} · ${htmlEscape(lesson.short.toUpperCase())}</span><h2 style="font-size:clamp(23px,3vw,32px);margin-top:13px">${htmlEscape(lesson.title)}</h2><p>${htmlEscape(lesson.assignment)}. Follow the structured study blocks and mark each completed task.</p><div class="btn-row"><a href="#/day/${d}" class="btn primary">▶ Continue Day ${d}</a><a href="#/roadmap" class="btn secondary">View learning path →</a></div></div><div class="hero-art">{ &lt;/&gt; }</div></section><section class="grid four"><div class="panel kpi"><div class="kpi-icon">◈</div><div class="small muted">Roadmap completed</div><div class="value">${s.blockPercent}%</div><div class="small muted">${s.doneBlocks} of 720 study blocks</div></div><div class="panel kpi"><div class="kpi-icon">◷</div><div class="small muted">Focused study time</div><div class="value">${(s.seconds/3600).toFixed(1)}<span class="small"> h</span></div><div class="small muted">720h recommended</div></div><div class="panel kpi"><div class="kpi-icon">◇</div><div class="small muted">Learning streak</div><div class="value">${s.streak}<span class="small"> days</span></div><div class="small muted">Completed study dates</div></div><div class="panel kpi"><div class="kpi-icon">✓</div><div class="small muted">Today's completion</div><div class="value">${percent(rec.blocks.length,6)}%</div><div class="small muted">${rec.blocks.length}/6 learning blocks</div></div></section><section><div class="section-title"><h2>Praveen vs Sanchita · Live competition</h2><button class="btn small-btn secondary" data-action="refresh-peer">↻ Refresh teammate</button></div>${syncNotice()}${scorePanel()}<div class="grid two">${duoCards()}</div><div class="btn-row" style="margin-top:16px"><a class="btn primary" href="#/duo">🏆 See completed lessons and leaderboard →</a></div></section><section class="split"><div class="panel"><div class="panel-heading"><div><h2>Today's learning schedule</h2><div class="subtitle">Six hours of active learning · breaks excluded</div></div><span class="pill">360 min</span></div>${lesson.blocks.map((b,i)=>`<div class="task-line"><span class="task-num" style="${rec.blocks.includes(i)?'background:#194737;color:#89f3c3':''}">${rec.blocks.includes(i)?'✓':i+1}</span><div><div class="label">${htmlEscape(b.title)}</div><div class="detail">${htmlEscape(b.detail)}</div></div><span class="time">${b.minutes}m</span></div>`).join('')}<a href="#/day/${d}" class="btn primary" style="margin-top:14px">Start today's session →</a></div><div class="panel"><div class="panel-heading"><div><h2>Recommended video</h2><div class="subtitle">Watch inside your academy</div></div><span class="pill">▶</span></div><div class="video-box"><iframe src="${v.embed}" title="${htmlEscape(v.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><h3 style="margin-top:15px">${htmlEscape(v.title)}</h3><p class="muted small" style="margin:6px 0 15px">${htmlEscape(v.channel)} · ${htmlEscape(lesson.title)}</p><a href="${v.url}" target="_blank" rel="noopener noreferrer" class="btn secondary small-btn">Open on YouTube ↗</a></div></section>`}
function roadmap(){const d=getActiveDay();const phaseOptions=phases.map((p,i)=>`<option value="${i}" ${String(i)===String(currentPhase)?'selected':''}>${htmlEscape(p.name)}</option>`).join('');const relevant=curriculum.filter(x=>(currentPhase==='all'||String(x.phaseIndex)===String(currentPhase))&&`${x.day} ${x.title} ${x.phase}`.toLowerCase().includes(currentFilter.toLowerCase()));return `<section class="page-heading"><div><div class="eyebrow">STRUCTURED LEARNING PATH</div><h1>120 days. One goal.</h1><p>Complete lessons at your own pace. Your progress is tracked per learner.</p></div><a href="#/day/${d}" class="btn primary">Continue Day ${d} →</a></section><div class="panel"><div class="filters"><input id="roadmap-search" class="field" placeholder="Search by topic or day..." value="${htmlEscape(currentFilter)}"/><select class="field" id="phase-filter"><option value="all">All 8 phases</option>${phaseOptions}</select><button class="btn secondary" data-action="clear-filters">Clear</button></div><div class="day-grid" id="roadmap-days">${renderDayCards(relevant)}</div></div>`}
function renderDayCards(items){return items.length?items.map(l=>{const r=getRecord(state.activeId,l.day);const pct=percent(r.blocks?.length||0,6);return `<a class="day-card ${pct===100?'done':l.day===getActiveDay()?'selected':''}" href="#/day/${l.day}"><div class="day-meta"><span>DAY ${l.day}</span><span>${pct===100?'✓ Done':`${pct}%`}</span></div><div class="day-title">${htmlEscape(l.title)}</div><div class="small muted">${htmlEscape(l.short)}</div><div class="bar-tiny"><span style="width:${pct}%"></span></div></a>`}).join(''):'<div class="empty">No lessons match your search.</div>'}
function lessonPage(day){const l=curriculum[day-1];if(!l)return `<div class="empty">This day does not exist.</div>`;setDay(day);const r=getRecord(state.activeId,day),v=videos[l.videoKey],prev=Math.max(day-1,1),next=Math.min(day+1,120),total=Object.values(r.seconds||{}).reduce((a,b)=>a+(+b||0),0), quiz=l.quiz;return `<section class="page-heading"><div><div class="eyebrow">${htmlEscape(l.phase.toUpperCase())} · DAY ${day} / 120</div><h1>${htmlEscape(l.title)}</h1><p>Goal: ${htmlEscape(l.assignment)}</p></div><div class="btn-row"><a href="#/day/${prev}" class="btn secondary" ${day===1?'aria-disabled="true"':''}>← Previous</a><a href="#/day/${next}" class="btn secondary">Next →</a></div></section><div class="panel"><div class="progress-label"><span>Daily completion</span><strong id="day-progress-label">${percent(r.blocks.length,6)}% · ${r.blocks.length}/6 blocks</strong></div><div id="day-progress-bar">${progressBar(percent(r.blocks.length,6))}</div><p class="helper">Recorded active study time: <strong id="active-today">${duration(total)}</strong> / 06:00:00. Complete all six blocks to mark the day done.</p></div><section class="split"><div class="panel"><div class="panel-heading"><div><h2>Six-hour study plan</h2><div class="subtitle">Closing the tab pauses the timer. Saved time is restored when you return.</div></div><span class="pill success">360 minutes</span></div>${l.blocks.map((b,i)=>blockHTML(day,b,r,i)).join('')}</div><div class="grid" style="align-content:start"><div class="panel"><h2 style="margin-bottom:13px">Watch this lesson</h2><div class="video-box"><iframe src="${v.embed}" title="${htmlEscape(v.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><h3 style="margin-top:14px">${htmlEscape(v.title)}</h3><p class="small muted" style="margin:8px 0 12px">${htmlEscape(v.channel)}</p><div class="btn-row"><a href="${v.url}" target="_blank" rel="noopener noreferrer" class="btn secondary small-btn">Watch on YouTube ↗</a><a href="#/videos" class="btn secondary small-btn">All videos</a></div><p class="helper">If YouTube prevents embedding, use “Watch on YouTube”. Reuse relevant chapters across multiple days.</p></div><div class="panel"><h2 style="margin-bottom:12px">Independent assignment</h2><p class="leading">${htmlEscape(l.assignment)}.</p><hr/><h3>Today's Java DSA challenge</h3><p class="leading small" style="margin-top:7px">${htmlEscape(l.dsa)}. Implement and explain the complexity.</p><hr/><h3>Learning objectives</h3>${l.objectives.map(s=>`<p class="small muted" style="margin-top:9px">✓ ${htmlEscape(s)}</p>`).join('')}</div><div class="panel"><h2 style="margin-bottom:12px">Daily quiz</h2><p class="leading small">${htmlEscape(quiz[0])}</p>${quiz[1].map((opt,i)=>`<label class="quiz-option"><input type="radio" name="answer" value="${i}" ${r.quiz?.selected===i?'checked':''}/> ${htmlEscape(opt)}</label>`).join('')}<button class="btn primary" data-action="submit-quiz" data-day="${day}">Check answer</button><div id="quiz-feedback">${r.quiz?feedback(r.quiz,quiz):''}</div></div><div class="panel"><h2 style="margin-bottom:12px">Your learning journal</h2><textarea class="field notes" id="daily-notes" data-day="${day}" placeholder="What did you learn? What was difficult? What will you practice next?">${htmlEscape(r.notes||'')}</textarea><p class="helper">Saved automatically in this learner's own study history.</p></div></div></section>`}
function blockHTML(day,b,rec,i){const done=rec.blocks.includes(i),secs=rec.seconds?.[i]||0;return `<div class="block-card ${done?'completed':''}" id="block-${i}"><input class="check" aria-label="Mark ${htmlEscape(b.title)} complete" type="checkbox" data-action="toggle-block" data-day="${day}" data-block="${i}" ${done?'checked':''}/><div class="block-body"><div class="block-top"><div><strong>${i+1}. ${htmlEscape(b.title)}</strong><div class="small muted">${b.minutes} minutes · ${htmlEscape(b.kind)}</div></div><span class="clock" id="clock-${i}">${duration(secs)}</span></div><p>${htmlEscape(b.detail)}</p><div class="btn-row"><button class="btn small-btn ${running?.day===day&&running?.block===i?'primary':'secondary'}" data-action="timer-toggle" data-day="${day}" data-block="${i}">${running?.day===day&&running?.block===i?'Ⅱ Pause':'▶ Start / Resume'}</button><button class="btn small-btn secondary" data-action="timer-reset" data-day="${day}" data-block="${i}">↺ Reset timer</button></div></div></div>`}
function feedback(res,quiz){return `<div class="quiz-feedback ${res.correct?'':'wrong'}"><b>${res.correct?'Correct!':'Not quite.'}</b> ${htmlEscape(quiz[3])}</div>`}
function videosPage(){const v=videos[videoSelected]||videos.boot;return `<section class="page-heading"><div><div class="eyebrow">WATCH, PRACTICE, APPLY</div><h1>YouTube Learning Academy</h1><p>Free lessons from established educators, embedded where permitted.</p></div><span class="pill">${Object.keys(videos).length} curated resources</span></section><div class="split"><div class="panel"><div class="panel-heading"><h2>Featured lesson</h2><span class="pill success">▶ Embedded player</span></div><div class="video-box"><iframe src="${v.embed}" title="${htmlEscape(v.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><h3 style="margin-top:16px">${htmlEscape(v.title)}</h3><p class="small muted" style="margin:8px 0 14px">${htmlEscape(v.channel)}</p><div class="btn-row"><a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${v.url}">Open on YouTube ↗</a><button class="btn ${state.videoStatus[state.activeId]?.[videoSelected]?'primary':'secondary'}" data-action="watch-video" data-video="${videoSelected}">${state.videoStatus[state.activeId]?.[videoSelected]?'✓ Marked watched':'✓ Mark as watched'}</button></div><p class="helper">Watching is not automatically tracked. Mark a lesson watched after completing it.</p></div><div class="panel"><h2>How to study efficiently</h2><div class="task-line"><span class="task-num">1</span><div><b class="small">Watch actively</b><p class="small muted">Pause frequently and write an example in your own words.</p></div></div><div class="task-line"><span class="task-num">2</span><div><b class="small">Type and change the code</b><p class="small muted">Test each concept using modified inputs, not only a tutorial copy.</p></div></div><div class="task-line"><span class="task-num">3</span><div><b class="small">Build something independently</b><p class="small muted">Finish the day's assignment, test it, and record the result.</p></div></div><div class="tip" style="margin-top:18px">Video embedding is subject to YouTube and the creator's permissions. External links are provided as a fallback.</div></div></div><div class="panel"><div class="panel-heading"><h2>Complete course library</h2><span class="pill">Choose a resource</span></div><div class="video-list">${Object.entries(videos).map(([id,x])=>`<button class="video-card ${id===videoSelected?'active':''}" data-action="select-video" data-video="${id}"><div class="vid-icon">${id==='ai'||id==='rag'?'✧':'▷'}</div><h3>${htmlEscape(x.title)}</h3><p>${htmlEscape(x.channel)}</p><div style="margin-top:15px"><span class="pill ${state.videoStatus[state.activeId]?.[id]?'success':''}">${state.videoStatus[state.activeId]?.[id]?'✓ Watched':'Play video →'}</span></div></button>`).join('')}</div></div>`}
const projects=[
 ['Java Expense Tracker','Build CLI categories, persistent records, validation and a README.','Days 1–15'],
 ['Java DSA Repository','Implement and explain interview patterns with Java tests.','Days 16–35'],
 ['Spring Boot Employee API','Design entities, CRUD endpoints, pagination, validation and SQL persistence.','Days 36–56'],
 ['Secure Banking Backend','Implement authorization, password hashing, transfers and automated tests.','Days 57–68'],
 ['React TypeScript Dashboard','Build responsive forms, routing, API states and accessibility.','Days 69–83'],
 ['Docker + CI Portfolio','Containerize a Java app and automate build/tests with GitHub Actions.','Days 84–93'],
 ['AI Interview Assistant','Create safe AI workflow contracts, RAG designs and evaluation examples.','Days 94–108'],
 ['Final Full-Stack Capstone','Document, test and deploy a complete full-stack application.','Days 109–120']
];
function projectsPage(){const pj=state.projects[state.activeId]||{};return `<section class="page-heading"><div><div class="eyebrow">PORTFOLIO EVIDENCE</div><h1>Learn by shipping projects.</h1><p>Eight meaningful projects prove that you can build, test and explain real software.</p></div></section><div class="grid two">${projects.map((x,i)=>`<div class="panel project-card"><div class="btn-row" style="justify-content:space-between"><div class="proj-num">PROJECT ${String(i+1).padStart(2,'0')}</div><span class="pill">${x[2]}</span></div><h2>${htmlEscape(x[0])}</h2><p class="small muted">${htmlEscape(x[1])}</p><label class="small" style="display:flex;gap:9px;align-items:center"><input class="check" type="checkbox" data-action="project-toggle" data-project="${i}" ${pj[i]?.done?'checked':''}/> Completed with working code</label><label class="small muted">GitHub repository URL <input class="field" data-action="project-url" data-project="${i}" value="${htmlEscape(pj[i]?.url||'')}" placeholder="https://github.com/..."/></label></div>`).join('')}</div><div class="tip">Project completion is self-reported. Test locally and publish a README with what you implemented, screenshots, commands, and known limitations.</div>`}
function progressPage(){const ss=stats(state.activeId),personal=phases.map((p,i)=>{let entries=curriculum.filter(l=>l.phaseIndex===i);let done=entries.filter(l=>isDayComplete(getRecord(state.activeId,l.day))).length;return {...p,done,total:entries.length,pct:percent(done,entries.length)}});return `<section class="page-heading"><div><div class="eyebrow">YOUR JOURNEY IN NUMBERS</div><h1>Consistency creates confidence.</h1><p>This report is specific to ${htmlEscape(user().name)}. Switching profiles changes the statistics.</p></div><button class="btn secondary" data-action="export">↓ Export progress</button></section><div class="grid four"><div class="panel kpi"><div class="small muted">Days completed</div><div class="value">${ss.completed}<span class="small">/120</span></div></div><div class="panel kpi"><div class="small muted">Study time</div><div class="value">${shortDuration(ss.seconds)}</div></div><div class="panel kpi"><div class="small muted">Quizzes correct</div><div class="value">${ss.quizzes}</div></div><div class="panel kpi"><div class="small muted">Active streak</div><div class="value">${ss.streak}</div></div></div><div class="grid two"><div class="panel"><h2 style="margin-bottom:20px">Roadmap completion</h2><div class="progress-label"><span>Study tasks completed</span><strong>${ss.blockPercent}% · ${ss.doneBlocks}/720</strong></div>${progressBar(Number(ss.blockPercent))}<p class="helper">The bar advances after every checked study block. Fully completed days: ${ss.completed}/120.</p></div><div class="panel"><h2 style="margin-bottom:20px">Time logged</h2><div class="progress-label"><span>Active timer study time</span><strong>${(ss.seconds/3600).toFixed(1)} / ${totalHours}h</strong></div>${progressBar(percent(ss.seconds,720*3600),true)}<p class="helper">Only time logged while the tab is active counts. Completing a checkbox does not fabricate study minutes.</p></div></div><div class="panel"><div class="panel-heading"><h2>Progress by learning phase</h2><span class="pill">8 phases</span></div><div class="timeline">${personal.map(p=>`<div class="timeline-row"><b>${htmlEscape(p.short)}</b><div class="progress-track"><div class="progress-fill" style="width:${p.pct}%;background:${p.color}"></div></div><span class="muted">${p.done}/${p.total} days</span></div>`).join('')}</div></div><section><div class="section-title"><h2>Study buddy comparison</h2><button class="btn secondary small-btn" data-action="refresh-peer">↻ Refresh</button></div><div class="grid two">${duoCards()}</div></section>`}
function settingsPage(){const c=cloud.config,session=cloud.session,mine=state.users.filter(u=>u.id.startsWith('local-')),mode=cloud.available?'Configured':'Not configured';return `<section class="page-heading"><div><div class="eyebrow">SETUP, BACKUP, SYNCHRONIZE</div><h1>Your learning workspace.</h1><p>Personalize both learner profiles, preserve progress, and optionally connect two devices.</p></div></section><div class="grid two"><div class="panel settings-section"><h2>Your two learner profiles</h2><p class="small muted">Praveen and Sanchita have separate local histories. Cross-device mode uses individual cloud accounts.</p>${mine.map((u,i)=>`<div class="form-row"><label>Learner ${i+1}</label><div class="name-chip">${htmlEscape(u.name)}</div></div>`).join('')}<p class="helper">Progress remains saved after closing the tab or browser. Clearing browser data or using a different device may remove local progress.</p></div><div class="panel settings-section"><h2>Backup & restore</h2><p class="small muted">Export a JSON backup regularly. Import on another browser if you prefer manual transfer instead of cloud sync.</p><button class="btn secondary" data-action="export">↓ Export all local data</button><label class="small" for="import-file">Import a previously exported JSON backup</label><input class="field" type="file" id="import-file" accept="application/json,.json"/><button class="btn secondary" data-action="import">↑ Import backup</button><button class="btn danger" data-action="reset-current">Reset active learner's progress</button></div></div><div class="panel settings-section"><div class="panel-heading"><div><h2>Enable cross-device competition and automatic synchronization</h2><div class="subtitle">For two people on separate phones or laptops, a shared data service is required.</div></div><span class="pill">${mode}</span></div><div class="message warn">GitHub Pages and Vercel only host the frontend. Browser storage cannot synchronize progress across devices. Connect a free-tier Supabase project for real two-account cloud progress and a shared duo leaderboard.</div><div class="form-row" style="max-width:320px;margin-bottom:15px"><label>Who is using this device?</label><select class="field" id="my-learner"><option value="Praveen" ${state.preferredLearner!=='Sanchita'?'selected':''}>Praveen</option><option value="Sanchita" ${state.preferredLearner==='Sanchita'?'selected':''}>Sanchita</option></select></div><div class="form-grid"><div class="form-row"><label>Supabase project URL</label><input id="cloud-url" class="field" placeholder="https://YOUR-PROJECT.supabase.co" value="${htmlEscape(c.url||'')}"/></div><div class="form-row"><label>Supabase publishable key (NOT secret)</label><input id="cloud-key" class="field" placeholder="sb_publishable_..." value="${htmlEscape(c.key||'')}"/></div></div><div class="btn-row"><button class="btn secondary" data-action="save-cloud-config">Save cloud configuration</button><a class="btn secondary" href="https://supabase.com/dashboard/projects" target="_blank" rel="noopener noreferrer">Open Supabase ↗</a></div><p class="helper">Before signing in, run the included supabase-setup.sql in your own Supabase SQL editor. Never paste service_role or secret keys into this website. Only the public publishable key is intended for browser use.</p><hr/><div class="grid two">${session?.access_token?`<div class="settings-section"><h3>Signed in to cloud</h3><p class="small muted">${htmlEscape(session.user?.email||'Cloud account')}</p><div class="btn-row"><button class="btn primary" data-action="cloud-reload">↻ Restore / sync my data</button><button class="btn secondary" data-action="cloud-update-name">Save my selected name</button><button class="btn secondary" data-action="cloud-logout">Sign out of cloud</button></div></div><div class="settings-section"><h3>Connect with your friend</h3><div class="btn-row"><button class="btn primary" data-action="create-team">Create study duo</button></div><div class="form-row"><label>Join friend's invitation</label><input id="team-code" maxlength="24" class="field" placeholder="Invitation code"/></div><button class="btn secondary" data-action="join-team">Join duo</button><button class="btn secondary" data-action="refresh-peer">Refresh team</button><div id="team-info" class="small muted">${peer?.team?`Your duo code: <strong style="user-select:all;color:#8df4bb">${htmlEscape(peer.team.invite_code)}</strong>`:'No duo loaded yet.'}</div></div>`:`<div class="settings-section"><h3>Register a cloud account</h3><div class="form-row"><label>Email</label><input class="field" id="auth-signup-email" type="email" autocomplete="email"/></div><div class="form-row"><label>Password (minimum 8 characters)</label><input class="field" id="auth-signup-pass" type="password" autocomplete="new-password"/></div><button class="btn secondary" data-action="cloud-signup">Create account</button><p class="helper">Verify your email if Supabase requests confirmation.</p></div><div class="settings-section"><h3>Sign into existing account</h3><div class="form-row"><label>Email</label><input class="field" id="auth-login-email" type="email" autocomplete="username"/></div><div class="form-row"><label>Password</label><input class="field" id="auth-login-pass" type="password" autocomplete="current-password"/></div><button class="btn primary" data-action="cloud-login">Sign in & sync</button></div>`}</div></div>`}
function render(){pauseTimer(false);let route=location.hash.slice(1)||'/dashboard';let page;if(route==='/dashboard')page=dashboard();else if(route==='/duo')page=duoPage();else if(route==='/roadmap')page=roadmap();else if(route==='/videos')page=videosPage();else if(route==='/projects')page=projectsPage();else if(route==='/progress')page=progressPage();else if(route==='/settings')page=settingsPage();else if(/^\/day\/\d+$/.test(route))page=lessonPage(Number(route.split('/')[2]));else page=dashboard();layout(page);attachEvents();updateTimers()}
function recordTimer(){if(!running)return;let now=Date.now(),delta=Math.max(0,Math.floor((now-running.lastTick)/1000));if(delta<1)return;let {day,block,id}=running;let cap=curriculum[day-1].blocks[block].minutes*60;let rec=ensureRecord(id,day);rec.seconds??={};rec.seconds[block]=Math.min(cap,(rec.seconds[block]||0)+delta);running.lastTick+=delta*1000;rec.updatedAt=Date.now();save();if(rec.seconds[block]>=cap){pauseTimer();message('Focus block completed! Mark the activity done.');render()}}
function pauseTimer(commit=true){if(running&&commit){recordTimerSimple();queueCloudSave(running.day)}running=null}
function recordTimerSimple(){if(!running)return;let {day,block,id}=running;let rec=ensureRecord(id,day);let delta=Math.max(0,Math.floor((Date.now()-running.lastTick)/1000));let cap=curriculum[day-1].blocks[block].minutes*60;rec.seconds[block]=Math.min(cap,(rec.seconds[block]||0)+delta);rec.updatedAt=Date.now();save()}
function updateTimers(){const route=location.hash.slice(1);if(!route.startsWith('/day/'))return;let day=Number(route.split('/')[2]),r=getRecord(state.activeId,day);for(let i=0;i<6;i++){const e=$(`#clock-${i}`);if(e)e.textContent=duration(r.seconds?.[i]||0)}const t=$('#active-today');if(t)t.textContent=duration(Object.values(r.seconds||{}).reduce((a,b)=>a+b,0))}
function tick(){if(!running)return;if(document.visibilityState==='hidden'){pauseTimer();return}recordTimer();updateTimers()}
let interval=setInterval(tick,1000);
window.addEventListener('pagehide',()=>pauseTimer());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')pauseTimer();else render()});window.addEventListener('hashchange',()=>{pauseTimer();render();window.scrollTo(0,0)});
function attachEvents(){const search=$('#roadmap-search');if(search)search.addEventListener('input',e=>{currentFilter=e.target.value;$('#roadmap-days').innerHTML=renderDayCards(curriculum.filter(x=>(currentPhase==='all'||String(x.phaseIndex)===String(currentPhase))&&`${x.day} ${x.title} ${x.phase}`.toLowerCase().includes(currentFilter.toLowerCase())))});const filter=$('#phase-filter');if(filter)filter.addEventListener('change',e=>{currentPhase=e.target.value;render()});const duoSelect=$('#duo-day-select');if(duoSelect)duoSelect.addEventListener('change',e=>{duoSelectedDay=clamp(Number(e.target.value),1,120);render()});const who=$('#my-learner');if(who)who.addEventListener('change',e=>{state.preferredLearner=e.target.value;save();message('This device is set up for '+e.target.value+'. Sign in to your own cloud account.')});const notes=$('#daily-notes');if(notes)notes.addEventListener('input',e=>{const day=Number(e.target.dataset.day);mutate(day,r=>r.notes=e.target.value)});document.querySelectorAll('[data-action="profile-name"]').forEach(el=>el.addEventListener('change',e=>{const p=state.users.find(u=>u.id===e.target.dataset.user);if(p){p.name=e.target.value.trim().slice(0,48)||'Learner';save();render()}}));document.querySelectorAll('[data-action="project-url"]').forEach(el=>el.addEventListener('change',e=>{state.projects[state.activeId]??={};let p=Number(e.target.dataset.project);state.projects[state.activeId][p]??={};const value=e.target.value.trim();if(value&&!/^https:\/\/github\.com\//i.test(value)){message('Please enter a GitHub repository URL.',true);return}state.projects[state.activeId][p].url=value;save();queueMetaSave();message('Project link saved')}));}
async function refreshPeer(){if(!cloud.authenticated){message('Two local learner profiles are active. Configure Supabase for cross-device comparison.');return}try{peer=await cloud.getTeam();if(peer?.members)for(const member of peer.members){if(member.id===ownCloudId())continue;const records=await cloud.getProgress(member.id);const id=`cloud:${member.id}`;state.progress[id]=Object.fromEntries((records||[]).map(x=>[x.day,x.payload]));const meta=await cloud.getMeta(member.id);state.projects[id]=meta?.projects||{};let found=state.users.find(x=>x.id===id);if(found)found.name=member.display_name;else state.users.push({id,name:member.display_name});}lastPeerRefresh=Date.now();save();render();message('Study duo progress refreshed')}catch(e){message(e.message,true)}}
async function enterCloud(){try{if(!cloud.authenticated)return;const uid=ownCloudId(),pid=`cloud:${uid}`,name=state.preferredLearner||cloud.session.user.user_metadata?.display_name||'Praveen';let found=state.users.find(u=>u.id===pid);if(!found)state.users.push({id:pid,name});state.activeId=pid;let existing=await cloud.getMyProfile();const desiredName=existing?.display_name&&existing.display_name!=='Learner'?existing.display_name:name;await cloud.upsertProfile(desiredName);state.users.find(u=>u.id===pid).name=desiredName;state.preferredLearner=desiredName==='Sanchita'?'Sanchita':'Praveen';const records=await cloud.getProgress(uid);const remote=Object.fromEntries((records||[]).map(r=>[r.day,r.payload]));const local=state.progress[pid]||{};const merged={...remote};const pending=[];for(const [k,value] of Object.entries(local)){if(!remote[k]||(Number(value.updatedAt)||0)>(Number(remote[k].updatedAt)||0)){merged[k]=value;pending.push(Number(k))}}state.progress[pid]=merged;const myMeta=await cloud.getMeta(uid);if(myMeta){state.projects[pid]=myMeta.projects||{};state.videoStatus[pid]=myMeta.video_status||{};state.activeDays[pid]=myMeta.active_day||state.activeDays[pid]||1;}save();for(const day of pending){if(day>=1&&day<=120){try{await cloud.saveDay(day,merged[day])}catch(e){lastCloudError=e.message}}}peer=await cloud.getTeam();if(peer?.members)for(let member of peer.members){if(member.id===uid)continue;const otherRows=await cloud.getProgress(member.id);state.progress[`cloud:${member.id}`]=Object.fromEntries(otherRows.map(x=>[x.day,x.payload]));const otherMeta=await cloud.getMeta(member.id);state.projects[`cloud:${member.id}`]=otherMeta?.projects||{};state.videoStatus[`cloud:${member.id}`]=otherMeta?.video_status||{};let old=state.users.find(x=>x.id===`cloud:${member.id}`);if(old)old.name=member.display_name;else state.users.push({id:`cloud:${member.id}`,name:member.display_name})}lastPeerRefresh=Date.now();save();render();message('Cloud account ready. Progress is restored.')}catch(e){message(`Cloud connection: ${e.message}`,true);render()}}
const randomize=()=>{};
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(!btn)return;let action=btn.dataset.action;const day=Number(btn.dataset.day)||getActiveDay(),block=Number(btn.dataset.block);try{
 if(action==='duo-select-day'){duoSelectedDay=clamp(Number(btn.dataset.day),1,120);render();$('#duo-day-select')?.scrollIntoView({behavior:'smooth',block:'center'})}
 else if(action==='duo-prev'){duoSelectedDay=Math.max(1,duoSelectedDay-1);render()}
 else if(action==='duo-next'){duoSelectedDay=Math.min(120,duoSelectedDay+1);render()}
 else if(action==='toggle-block'){pauseTimer();mutate(day,r=>{r.blocks??=[];r.blocks=r.blocks.includes(block)?r.blocks.filter(x=>x!==block):[...r.blocks,block].sort((a,b)=>a-b)});render();}
 else if(action==='timer-toggle'){if(running&&running.day===day&&running.block===block){pauseTimer();render()}else{pauseTimer();running={id:state.activeId,day,block,lastTick:Date.now()};renderWithoutPausing();}}
 else if(action==='timer-reset'){if(confirm('Reset the recorded timer for this block?')){if(running&&running.day===day&&running.block===block)pauseTimer();mutate(day,r=>r.seconds[block]=0);render()}}
 else if(action==='submit-quiz'){let checked=$('input[name="answer"]:checked');if(!checked){message('Select one answer first.',true);return}let correct=Number(checked.value)===curriculum[day-1].quiz[2];mutate(day,r=>r.quiz={selected:Number(checked.value),correct});$('#quiz-feedback').innerHTML=feedback({correct},curriculum[day-1].quiz);message(correct?'Correct answer!':'Review the explanation and try again.')}
 else if(action==='project-toggle'){let p=Number(btn.dataset.project);state.projects[state.activeId]??={};state.projects[state.activeId][p]??={};state.projects[state.activeId][p].done=btn.checked;save();queueMetaSave();message('Project status saved')}
 else if(action==='select-video'){videoSelected=btn.dataset.video;render()}
 else if(action==='watch-video'){state.videoStatus[state.activeId]??={};const v=btn.dataset.video;state.videoStatus[state.activeId][v]=!state.videoStatus[state.activeId][v];save();queueMetaSave();render()}
 else if(action==='clear-filters'){currentFilter='';currentPhase='all';render()}
 else if(action==='export'){const data={format:'v2-backup',date:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`v2-backup-${todayISO()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),2000);message('Backup downloaded')}
 else if(action==='import'){const file=$('#import-file')?.files?.[0];if(!file){message('Select a JSON backup file.',true);return}if(file.size>8*1024*1024)throw Error('Backup file is too large');let parsed=JSON.parse(await file.text());if(!['v2-backup', ['dev','launch-duo-backup'].join('')].includes(parsed.format)||parsed.state?.version!==3||!Array.isArray(parsed.state.users)||typeof parsed.state.progress!=='object'||!parsed.state.progress)throw Error('Invalid V2 backup');if(confirm('Replace current local progress with this backup?')){pauseTimer();state={...newState(),...parsed.state};save();render();message('Backup imported successfully')}}
 else if(action==='reset-current'){if(confirm(`Reset ALL progress for ${user().name}? This cannot be undone without a backup.`)){const id=state.activeId;if(isCloud()&&cloud.authenticated){await cloud.api(`day_progress?user_id=eq.${encodeURIComponent(ownCloudId())}`,{method:'DELETE'});}state.progress[id]={};state.projects[id]={};state.videoStatus[id]={};state.activeDays[id]=1;save();queueMetaSave();render();message('Active learner progress reset')}}
 else if(action==='save-cloud-config'){cloud.configure($('#cloud-url').value,$('#cloud-key').value);message('Cloud configuration saved');render()}
 else if(action==='cloud-signup'){let email=$('#auth-signup-email').value.trim(),password=$('#auth-signup-pass').value;if(!email||password.length<8)throw Error('Use an email and password with at least 8 characters');await cloud.signup(email,password,state.preferredLearner||'Praveen');message('Account created. Check email verification if required, then sign in.');}
 else if(action==='cloud-login'){let email=$('#auth-login-email').value.trim(),password=$('#auth-login-pass').value;if(!email||!password)throw Error('Enter your email and password');await cloud.signin(email,password);await enterCloud()}
 else if(action==='cloud-logout'){cloud.logout();peer=null;state.activeId='local-you';save();render();message('Signed out of cloud. Your local profiles remain saved.')}
 else if(action==='cloud-reload'){await enterCloud()}
 else if(action==='cloud-update-name'){if(!cloud.authenticated)throw Error('Sign in first');const name=state.preferredLearner||'Praveen';await cloud.upsertProfile(name);let mine=state.users.find(x=>x.id===`cloud:${ownCloudId()}`);if(mine)mine.name=name;save();await refreshPeer();message('Cloud profile name saved as '+name)}
 else if(action==='create-team'){if(!cloud.authenticated)throw Error('Sign in to cloud first');let existing=await cloud.getTeam();if(existing?.team){message(`Duo already exists. Invite code: ${existing.team.invite_code}`);peer=existing;render();return}let code=await cloud.createTeam();message(`Duo created! Code: ${code}`);await refreshPeer()}
 else if(action==='join-team'){let code=$('#team-code')?.value?.trim();if(!code)throw Error('Enter invitation code');await cloud.joinTeam(code);await refreshPeer()}
 else if(action==='refresh-peer'){await refreshPeer()}
 }catch(err){console.error(err);message(err.message||'Something went wrong',true)}});
function renderWithoutPausing(){let x=running;running=null;render();running=x;const button=document.querySelector(`[data-action="timer-toggle"][data-day="${x.day}"][data-block="${x.block}"]`);if(button){button.textContent='Ⅱ Pause';button.classList.add('primary');button.classList.remove('secondary')}message('Focus timer started. It pauses when the tab is closed or hidden.')}

if(!location.hash)location.replace(`${location.pathname}${location.search}#/dashboard`);
render();
if(cloud.authenticated&&cloud.available)enterCloud();
// Read-only partner progress is pulled about every 15s while the page is visible.
setInterval(async()=>{if(cloud.authenticated&&isCloud()&&document.visibilityState==='visible'&&!syncing){syncing=true;try{let p=await cloud.getTeam();if(p?.members){peer=p;for(let m of p.members){if(m.id===ownCloudId())continue;let rows=await cloud.getProgress(m.id);state.progress[`cloud:${m.id}`]=Object.fromEntries(rows.map(x=>[x.day,x.payload]));let meta=await cloud.getMeta(m.id);state.projects[`cloud:${m.id}`]=meta?.projects||{};lastPeerRefresh=Date.now();let u=state.users.find(x=>x.id===`cloud:${m.id}`);if(u)u.name=m.display_name;else state.users.push({id:`cloud:${m.id}`,name:m.display_name})}save();if(['/dashboard','/duo','/progress'].includes(location.hash.slice(1))&&!running)render();}}catch(err){lastCloudError=err.message}finally{syncing=false}}},15000);
